--
-- Each require() loads in its own Lua scope so a syntax error in one module
-- doesn't take down the rest of the config.

-- Visual styling: general/group/misc/render/dwindle/master/decoration/animations
require("config.appearance")

-- Monitor profiles (generated by hyprmoncfg — do not edit by hand).
-- Lives at the top level, not under config/, because config/ holds authored
-- modules and this file is machine state rewritten on every profile apply.
-- Must stay a bare require(): hyprmoncfg parses this file to verify its output
-- is actually included, and it does not recognise pcall(require, ...) — wrapping
-- it makes every `hyprmoncfg apply` fail. The setup script seeds an empty
-- monitors.lua on fresh machines so this never resolves against a missing file.
require("monitors")

-- Input, cursor, touchpad, gestures, binds {} settings
require("config.input")

-- Window rules (quake terminal, etc.)
require("config.windowrules")

-- Key + mouse bindings and the resize submap
require("config.keybinds")

-- Environment variables and exec-once startup chain
require("config.autostart")
